use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(matrix) = input {
        let n = matrix.len();
        let mut main_diagonal_sum = 0;
        let mut anti_diagonal_sum = 0;

        for i in 0..n {
            if let Value::Number(num) = &matrix[i][i] {
                main_diagonal_sum += num.as_i64().unwrap();
            }
            if let Value::Number(num) = &matrix[i][n - 1 - i] {
                anti_diagonal_sum += num.as_i64().unwrap();
            }
        }

        Value::Array(vec![
            Value::Number(main_diagonal_sum.into()),
            Value::Number(anti_diagonal_sum.into()),
        ])
    } else {
        Value::Null
    }
}
